import{z as p,x as l,o as e,c as i,q as t,j as A,D as E,d as s,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"PTP / GPS 对时","description":"","frontmatter":{"title":"PTP / GPS 对时","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ptp-gps-sync.md","filePath":"quant/ptp-gps-sync.md","lastUpdated":1791063341000}'),o={name:"quant/ptp-gps-sync.md"};function P(d,a,T,F,c,h){const B=l("Mermaid");return e(),i("div",null,[a[2]||(a[2]=t('<h1 id="ptp-gps-对时" tabindex="-1">PTP / GPS 对时 <a class="header-anchor" href="#ptp-gps-对时" aria-label="Permalink to &quot;PTP / GPS 对时&quot;">​</a></h1><div class="epigraph"><p>两台引擎的纳秒时间戳只有在同步到同一时间基之后才能相减。未校准的「领先 50 微秒」可能只是两台钟差了 50 微秒。</p><footer>—— 据 IEEE 1588 PTP 与卫星授时的公开技术标准；对照 MiFID II RTS 与 FINRA 对业务时钟同步精度的监管要求</footer></div><p><a href="/quant/exchange-broker-clocks">交易所时间戳与经纪商时间戳</a>要求读懂字段。本课的缺口是：不同场所、SIP、经纪商的匹配时间即使都叫 UTC，振荡器仍会漂。GPS 提供时间基，PTP（IEEE 1588）在机房内分发。监管（如 MiFID II 的 RTS 对时钟精度、FINRA 对业务时钟）把同步从工程偏好变成合规。本课写对时如何进入跨所研究与 NBBO 构造，不写如何建设机房授时，也不写如何利用残留钟差去交易。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>跨所领先滞后、合成 NBBO、延迟套利检验，都要比较 \\(t_A\\) 与 \\(t_B\\)。若 A 所的钟快 30 微秒，A 会在所有研究里「领先」。Hasbrouck 信息份额对时钟误差敏感。缺口是在合并前得到一个共同时间基，并报告残留误差上限。监管给出的最大偏离（例如相对 UTC 的若干微秒）是合规上限，不是你样本里的实际误差。研究应尽量用交易所提供的同步质量字段或官方对时说明，而不是假设合规即无误差。</p><p><span class="marginnote">直觉类比：两只手表差 5 分钟时，看「快表」的人每次都显得先到。你说 A 所「领先 50 微秒」，可能只是 A 的钟快了 50 微秒——先把表对齐，再谈谁跑得快。</span></p><p>SIP 与直连的分叉，一部分是真延迟，一部分是两套钟。不对时，分叉被高估或低估。系统课里 <code>exch_ts - local_ts</code> 更是钟差加传输；要分解必须先把本地钟也同步，否则延迟预算的测量无定义。</p><h3 id="gps、ptp、ntp-不是同一精度" tabindex="-1">GPS、PTP、NTP 不是同一精度 <a class="header-anchor" href="#gps、ptp、ntp-不是同一精度" aria-label="Permalink to &quot;GPS、PTP、NTP 不是同一精度&quot;">​</a></h3><p>NTP 在公网是毫秒级，不够高频跨所。GPS 提供 UTC 参照，天线与接收质量影响。PTP 在良好网络下可达亚微秒到微秒。研究不需要自己达到交易所精度，但需要知道数据源声称的精度，并在结论里把「小于该精度的领先」视为无法识别。把 3 微秒的领先写成价格发现，当馈送精度是 50 微秒时，是假结果。</p><p><span class="marginnote">数字实例：公网 NTP 约毫秒级，即 1000 微秒；若要检验的「领先」只有 3 微秒，用 NTP 对时等于用米尺量头发丝——仪器粗了约三百倍，结论只能是「测不出来」。</span></p><p><span class="marginnote">卫星授时有闰秒、天线遮挡、欺骗干扰等已知问题。交易场所通常有冗余。研究侧把「GPS」三个字写进论文，不等于样本已校准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合并多所数据前：读取各源关于时钟同步的文档与质量标志；若有交易所间的官方偏移，应用偏移。没有偏移时，用极度活跃的交叉上市或期货现货对，估计固定偏移（注意这会把真领先吸进偏移——只能当敏感性，不能当真理）。报告：识别阈 = 声称精度之和。小于阈值的领先滞后不解释为经济。</p>',13)),(e(),A(n,null,{default:E(()=>[r(B,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOC%5B%22%E8%AF%BB%E5%8F%96%E5%90%84%E6%BA%90%E5%90%8C%E6%AD%A5%E6%96%87%E6%A1%A3%E4%B8%8E%E8%B4%A8%E9%87%8F%E6%A0%87%E5%BF%97%22%5D%20--%3E%20OFF%7B%22%E6%9C%89%E5%AE%98%E6%96%B9%E9%92%9F%E5%B7%AE%E5%81%8F%E7%A7%BB%E5%8F%AF%E7%94%A8%E5%90%97%22%7D%0A%20%20OFF%20--%3E%7C%22%E6%9C%89%22%7C%20APPLY%5B%22%E5%BA%94%E7%94%A8%E5%AE%98%E6%96%B9%E5%81%8F%E7%A7%BB%E5%90%8E%E5%86%8D%E5%90%88%E5%B9%B6%22%5D%0A%20%20OFF%20--%3E%7C%22%E6%97%A0%22%7C%20EST%5B%22%E7%94%A8%E4%BA%A4%E5%8F%89%E4%B8%8A%E5%B8%82%E5%AF%B9%E4%BC%B0%E5%9B%BA%E5%AE%9A%E5%81%8F%E7%A7%BB%EF%BC%8C%E4%BB%85%E4%BD%9C%E6%95%8F%E6%84%9F%E6%80%A7%22%5D%0A%20%20APPLY%20--%3E%20TH%5B%22%E8%AF%86%E5%88%AB%E9%98%88%20%3D%20%E4%B8%A4%E6%BA%90%E5%A3%B0%E7%A7%B0%E7%B2%BE%E5%BA%A6%E4%B9%8B%E5%92%8C%22%5D%0A%20%20EST%20--%3E%20TH%0A%20%20TH%20--%3E%20OK%5B%22%E6%97%B6%E5%B7%AE%E8%B6%85%E8%BF%87%E9%98%88%EF%BC%9A%E5%8F%AF%E8%A7%A3%E9%87%8A%E4%B8%BA%E9%A2%86%E5%85%88%E6%BB%9E%E5%90%8E%22%5D%0A%20%20TH%20--%3E%20NO%5B%22%E6%97%B6%E5%B7%AE%E5%B0%8F%E4%BA%8E%E9%98%88%EF%BC%9A%E8%A7%86%E4%B8%BA%E6%B5%8B%E9%87%8F%E8%AF%AF%E5%B7%AE%EF%BC%8C%E4%B8%8D%E8%A7%A3%E9%87%8A%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>本地研究集群若用于到达时间，应用 PTP 或至少 GPS，并记录与 UTC 的偏移日志。偏移突变日应从延迟样本中剔除。这与序号缺口一样，是质量事件。</p><h3 id="对时与监管时间戳" tabindex="-1">对时与监管时间戳 <a class="header-anchor" href="#对时与监管时间戳" aria-label="Permalink to &quot;对时与监管时间戳&quot;">​</a></h3><p>MiFID II 等要求报告交易的时钟同步到规定精度，精度随交易类型变化。这使欧洲磁带比早期美股秒级 TAQ 更可比，仍不意味着你可以解释亚微秒。TRACE 的报告时钟是经销商业务钟，精度与股票引擎不可比，见最后一课。不要把股票 PTP 的语言套到债券打印上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同步误差是加在真事件时间上的测量误差。领先滞后回归把测量误差当成因果。信息份额把先动的钟当成信息源。NBBO 若用未校准时间取 \\(\\max b\\)、\\(\\min a\\)，可能把「尚未发生」的报价拼进去，造成虚假交叉。对时是市场数据的识别条件，就像方向分类是价差分解的识别条件。</p><p><span class="marginnote">常见误区：以为「两条数据都有时间戳，相减就是真实间隔」。时间戳是测量值，不是事件本身，钟差与传输延迟都掺在里面。对时做的事，是把测量误差压到小于你要研究的效应，差才有意义。</span></p><p><span class="marginnote">加密各所自行授时，跨所「领先」文献尤其容易是钟差。没有共同 GPS 基，不要做毫秒级价格发现排序。</span></p>',7)),(e(),A(n,null,{default:E(()=>[r(B,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20LR%0A%20%20GPS%5B%22GPS%20%2F%20UTC%20%E6%97%B6%E9%97%B4%E5%9F%BA%22%5D%20--%3E%20PTP%5B%22%E6%9C%BA%E6%88%BF%20PTP%20%E5%88%86%E5%8F%91%22%5D%0A%20%20PTP%20--%3E%20A%5B%22%E5%9C%BA%E6%89%80%20A%20%E5%8C%B9%E9%85%8D%E9%92%9F%22%5D%0A%20%20PTP%20--%3E%20B%5B%22%E5%9C%BA%E6%89%80%20B%20%E5%8C%B9%E9%85%8D%E9%92%9F%22%5D%0A%20%20A%20--%3E%20CMP%5B%22%E5%8F%AF%E6%AF%94%E8%BE%83%E7%9A%84%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%22%5D%0A%20%20B%20--%3E%20CMP%0A%20%20ERR%5B%22%E6%AE%8B%E7%95%99%E9%92%9F%E5%B7%AE%E4%B8%8A%E9%99%90%22%5D%20--%3E%20CMP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h3 id="识别阈以下的领先不做经济解释" tabindex="-1">识别阈以下的领先不做经济解释 <a class="header-anchor" href="#识别阈以下的领先不做经济解释" aria-label="Permalink to &quot;识别阈以下的领先不做经济解释&quot;">​</a></h3><p>两套馈送声称精度之和，构成可识别的最小时差。把 3 微秒的领先写成价格发现，当精度是 50 微秒时，是测量误差叙事。结论应在阈值之上稳健。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论授时攻击。研究结论应在残留误差下稳健。下一课在已对时（或已声明未对时）的前提下构造 NBBO。</p><p><span class="marginnote">用交叉上市估计固定钟差，会把真的领先吸进偏移。该方法只能当敏感性，不能当已校准的时间基。监管合规上限同样不是样本实际误差。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨所时间相减的前提是共同时间基；否则领先可能是钟差。</li><li>识别阈由馈送声称精度决定，阈下不做经济解释。</li><li>GPS 提供基，PTP 分发；NTP 不够高频跨所。</li><li>合规上限 ≠ 样本实际误差，要读质量字段。</li><li>债券与加密的时钟精度通常不可与股票引擎比。</li><li>出处：IEEE 1588；MiFID II 时钟同步监管技术标准；FINRA 业务时钟要求；Hasbrouck 对多市场度量的数据前提。</li></ul>',7))])}const m=p(o,[["render",P]]);export{C as __pageData,m as default};
